function numberOfSpecialSubstrings(s) {
  const count = new Array(26).fill(0);
  let left = 0;
  let total = 0;

  for (let right = 0; right < s.length; right++) {
    const letter = s.charCodeAt(right) - 97;
    count[letter]++;
    while (count[letter] > 1) {
      count[s.charCodeAt(left) - 97]--;
      left++;
    }
    total += right - left + 1;
  }
  return total;
}

