function numberOfSpecialSubstrings(s) {
  let total = 0;
  for (let start = 0; start < s.length; start++) {
    const seen = new Set();
    for (let end = start; end < s.length && !seen.has(s[end]); end++) {
      seen.add(s[end]);
      total++;
    }
  }
  return total;
}

