function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const pickAlphabet = () => {
    const r = rand();
    if (r < 0.2) return 1 + Math.floor(rand() * 2);
    if (r < 0.7) return 2 + Math.floor(rand() * 5);
    return 26;
  };
  const k = pickAlphabet();
  const n = size === 'large' ? 9000 + Math.floor(rand() * 1001) : 1 + Math.floor(rand() * 12);
  let s = '';
  for (let i = 0; i < n; i++) s += letters[Math.floor(rand() * k)];
  return [s];
}
